import javax.inject.Inject
import com.cloudsbay.brewbyadarsh.features.auth.domain.usecases.IsAuthenticatedUseCase

class AuthChecker @Inject constructor(
    private val isAuthenticatedUseCase: IsAuthenticatedUseCase
) {

    suspend fun checkAuthentication(): Boolean {
        return isAuthenticatedUseCase()
    }

    // Usage in repository or service:
    suspend fun performSecureOperation(): Result {
        if (!checkAuthentication()) {
            throw NotAuthenticatedException("User must be logged in")
        }
        // Perform operation
        return result
    }
