// EXAMPLE 5: Password Reset Flow

import com.cloudsbay.brewbyadarsh.features.auth.domain.usecases.ResetPasswordUseCase

@HiltViewModel
class PasswordResetViewModel @Inject constructor(
    private val resetPasswordUseCase: ResetPasswordUseCase
) : ViewModel() {

    private val _resetState = MutableStateFlow<ResetState>(ResetState.Idle)
    val resetState: StateFlow<ResetState> = _resetState.asStateFlow()

    fun resetPassword(email: String) {
        viewModelScope.launch {
            _resetState.value = ResetState.Loading

            val result = resetPasswordUseCase(email)
            _resetState.value = when (result) {
                is AuthResult.Success -> {
                    ResetState.Success("Check your email for reset instructions")
                }
                is AuthResult.Error -> {
                    ResetState.Error(result.message)
                }
                is AuthResult.Loading -> ResetState.Loading
            }
        }
    }
}

sealed class ResetState {
    object Idle : ResetState()
    object Loading : ResetState()
    data class Success(val message: String) : ResetState()
    data class Error(val message: String) : ResetState()
}


// EXAMPLE 6: Session Refresh

import com.cloudsbay.brewbyadarsh.features.auth.domain.usecases.RefreshSessionUseCase

class SessionManager @Inject constructor(
    private val refreshSessionUseCase: RefreshSessionUseCase,
    private val getAccessTokenUseCase: GetAccessTokenUseCase
) {

    suspend fun ensureValidSession() {
        when (val result = refreshSessionUseCase()) {
            is AuthResult.Success -> {
                println("Session refreshed, expires at: ${result.data.expiresAt}")
            }
            is AuthResult.Error -> {
                throw SessionExpired("Session refresh failed: ${result.message}")
            }
            is AuthResult.Loading -> {}
        }
    }

    suspend fun getValidAccessToken(): String? {
        ensureValidSession()
        return getAccessTokenUseCase()
    }
}


// EXAMPLE 7: Interceptor for API calls with auth token

import io.ktor.client.plugins.auth.Auth
import io.ktor.client.plugins.auth.providers.BearerTokenProvider

class AuthInterceptor @Inject constructor(
    private val sessionManager: SessionManager
) {

    fun setupKtorAuth(client: HttpClientConfig<*>) {
        client.install(Auth) {
            bearer {
                loadTokens {
                    BearerTokens(
                        accessToken = sessionManager.getValidAccessToken() ?: "",
                        refreshToken = ""
                    )
                }
            }
        }
    }
}


// EXAMPLE 8: Get current user

import com.cloudsbay.brewbyadarsh.features.auth.domain.usecases.GetCurrentUserUseCase

@HiltViewModel
class UserProfileViewModel @Inject constructor(
    private val getCurrentUserUseCase: GetCurrentUserUseCase
) : ViewModel() {

    private val _userState = MutableStateFlow<UserState>(UserState.Loading)
    val userState: StateFlow<UserState> = _userState.asStateFlow()

    init {
        loadCurrentUser()
    }

    private fun loadCurrentUser() {
        viewModelScope.launch {
            val result = getCurrentUserUseCase()
            _userState.value = when (result) {
                is AuthResult.Success -> {
                    if (result.data != null) {
                        UserState.Success(result.data)
                    } else {
                        UserState.NotAuthenticated
                    }
                }
                is AuthResult.Error -> UserState.Error(result.message)
                is AuthResult.Loading -> UserState.Loading
            }
        }
    }
}

sealed class UserState {
    object Loading : UserState()
    data class Success(val user: AuthUser) : UserState()
    object NotAuthenticated : UserState()
    data class Error(val message: String) : UserState()
}


