// EXAMPLE 10: Protected API calls with session handling

import com.cloudsbay.brewbyadarsh.features.auth.domain.usecases.GetCurrentSessionUseCase

class SecureApiClient @Inject constructor(
    private val getCurrentSessionUseCase: GetCurrentSessionUseCase,
    private val retrofit: Retrofit
) {

    suspend fun makeSecureApiCall(): ApiResponse {
        // Get current session
        when (val result = getCurrentSessionUseCase()) {
            is AuthResult.Success -> {
                val session = result.data ?: throw NotAuthenticatedException()
                // Use session.accessToken for API calls
                return makeApiCallWithToken(session.accessToken)
            }
            is AuthResult.Error -> throw Exception(result.message)
            is AuthResult.Loading -> throw Exception("Auth is loading")
        }
    }

    private suspend fun makeApiCallWithToken(token: String): ApiResponse {
        // Make API call with token in Authorization header
        // Authorization: Bearer $token
        return ApiResponse()
    }
}

